script.text:

function load$GridVoucherDetail$(g) {
	g.add_itemValueChanged(onChange$GridVoucherDetail$);
	g.add_onResponseComplete(on$GridVoucherDetail$ResponseComplete);
	g.add_commandEvent(on$GridVoucherDetail$ExecuteCommand);
	&FormulaExpression;
	g.$h = [['voucherCode', 'String', g._voucherCode], 'ngay_lct', 'ma_dvcs', 'stt_rec'];
	udf$Detail$(g);
	udf$Detail$PaymentControl(g);

	&ESG.LoadScriptHoverField;

}
/* <flatten type="Javascript"> */
function udf$Detail$PaymentControl(g) {
	if (!g.get_element().parentForm._udfPaymentControl) {
		udf$Field$(g, 'ma_tt');
		udf$Field$(g, 'so_ct0');
		udf$Field$(g, 'ngay_ct0');
	}
}
function dispose$GridVoucherDetail$(g) {
	g.$a = null;
	try {g.remove_commandEvent(on$GridVoucherDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridVoucherDetail$);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridVoucherDetail$ResponseComplete);} catch (ex) {}
}
function onChange$GridVoucherDetail$Account(o) {o.grid.request(o, 'Account', 'Account', ['tk'], o.grid.$h, true);}
function onChange$GridVoucherDetail$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 'ps_no_nt':
			g.executeExpression(o, ['[ps_co_nt]:=0']);
			g.validExpression(o, [g.$a.ps_no, g.$a.ps_co, g.$a.tien_nt, g.$a.tien, g.$a.thue_nt, g.$a.thue2, g.$a.tien_tt_nt, g.$a.tien_tt], [g.$a.t_ps_no_nt, g.$a.t_ps_co_nt, g.$a.t_ps_no, g.$a.t_ps_co, g.$a.t_tien_nt2, g.$a.t_tien2, g.$a.t_thue1_nt, g.$a.t_thue1], [g.$a.t_thue_nt, g.$a.t_thue], 'ps_co_nt');
			break;
		case 'ps_co_nt':
			g.executeExpression(o, ['[ps_no_nt]:=0']);
			g.validExpression(o, [g.$a.ps_co, g.$a.ps_no, g.$a.tien_nt, g.$a.tien, g.$a.thue_nt, g.$a.thue2, g.$a.tien_tt_nt, g.$a.tien_tt], [g.$a.t_ps_no_nt, g.$a.t_ps_co_nt, g.$a.t_ps_no, g.$a.t_ps_co, g.$a.t_tien_nt2, g.$a.t_tien2, g.$a.t_thue1_nt, g.$a.t_thue1], [g.$a.t_thue_nt, g.$a.t_thue], null);
			break;
		case 'ps_no':
			g.executeExpression(o, ['[ps_co]:=0']);
			g.validExpression(o, [g.$a.tien], [g.$a.t_ps_no, g.$a.t_ps_co, g.$a.thue2, g.$a.tien_tt, g.$a.t_tien2, g.$a.t_thue1_nt, g.$a.t_thue1], [g.$a.t_thue_nt, g.$a.t_thue], 'ps_co');
			break;
		case 'ps_co':
			g.executeExpression(o, ['[ps_no]:=0']);
			g.validExpression(o, [g.$a.tien], [g.$a.t_ps_no, g.$a.t_ps_co, g.$a.thue2, g.$a.tien_tt, g.$a.t_tien2, g.$a.t_thue1_nt, g.$a.t_thue1], [g.$a.t_thue_nt, g.$a.t_thue], null);
			break;
		default:
			break;
	}
}
/* </flatten> */
function on$GridVoucherDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		case 'AfterRemoveRow':
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterCloneRow':
			g.setItemFieldValue('stt_rec0', e.type.Value, '');
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterInsertRow':
			if (g._rowCount > 1) {
				var d1 = f.getItemValue('t_ps_no_nt') - f.getItemValue('t_ps_co_nt'), d2 = f.getItemValue('t_ps_no') - f.getItemValue('t_ps_co'), activeRow = g._activeRow;
				if (d1 > 0) {
					g._setItemValue(activeRow, g._getColumnOrder('ps_co_nt'), d1);
					g._setItemValue(activeRow, g._getColumnOrder('ps_co'), d2);
				}
				else {
					g._setItemValue(activeRow, g._getColumnOrder('ps_no_nt'), -d1);
					g._setItemValue(activeRow, g._getColumnOrder('ps_no'), -d2);
				}
				on$GridVoucherDetail$RowChange(g, f);
			}
			break;
		case 'Check':
			&ESG.ScriptCheck;
			if !g.validRowExpression('ma_td4', '(![f4_yn]) || ([ma_td4] != "")') break;
			if !g.validRowExpression('ma_kh', '(![tk_cn]) || ([ma_kh] != "")') break;
			if (1 == 1) {&ScriptTaxGridDetailCheck;}
			break;
		case 'ImportData':
			if (f._action == 'View') break;
			&ImportDetailImportDataCommand;;
			 break;
		 case 'Download':
			&UserDefinedDownload;
			break;
			&GridExtraToolbarExecuteCommandScript;;
			&ScriptTaxGridDetailValid;
		default:
			break;
	}
}
function on$GridVoucherDetail$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
	 case 'Account':
			g.setItemGridBehavior(o, [['tk_cn', result[0].Value, '', false], ['f4_yn', result[1].Value, null, null]]);
			break;
		case 'Download':
			g._key = result[0].Value;
			break;
		&ESG.ScriptGridResponse;
		&ScriptTaxGridDetailResponse;
		default:
			break;
	}
}
&ScriptTaxGridDetailFunction;
/* <flatten type="Javascript"> */
function on$GridVoucherDetail$RowChange(g, f) {g.executeAggregate([g.$a.t_ps_no_nt, g.$a.t_ps_co_nt, g.$a.t_ps_no, g.$a.t_ps_co]);}
/* </flatten> */

			&ImportDetailInsertResult;
			&ImportDetailScript;
			&DowloadScript;
			&GridExtraToolbarScript;
			&ESG.GridScript;

grid.response:
&XMLTaxGridDetailResponse;
if exists(select 1 from dmtk where tk = @tk and loai_tk = 1) begin declare @unitCode varchar(33) = case when @$ma_dvcs = '' then @@unit else @$ma_dvcs end, @f4_yn bit select @f4_yn = cast(case when exists(select 1 from dmtknh where ma_dvcs = @unitCode and tk = @tk) then 1 else 0 end as bit)
select tk_cn, @f4_yn as f4_yn from dmtk where tk = @tk return end
&CreateTicket; select @ticket as value return
&ESG.XMLGridResponse;
